select p.proname, md5(pg_get_functiondef(p.oid)) h, p.prosecdef definer, coalesce(array_to_string(p.proconfig, ','),'') cfg, pg_get_userbyid(p.proowner) owner, has_function_privilege('anon', p.oid, 'execute') anon, has_function_privilege('authenticated', p.oid, 'execute') app, has_function_privilege('service_role', p.oid, 'execute') svc from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('hdm_billing_claim_checkout','hdm_billing_checkout_lookup','hdm_billing_save_token','hdm_billing_apply_grow_event','hdm_billing_apply_grow_event_v1','hdm_billing_start_checkout','hdm_billing_pending_card_checkouts') order by 1
